L["  /msuf gfhoverdebug on|off|status - Debug group-frame hover + tooltip paths."] = "  /msuf gfhoverdebug on|off|status - Debug für Gruppenframe-Hover und Tooltip-Pfade."
L["  /msuf help      - Show this help."] = "  /msuf help      - Diese Hilfe anzeigen."
L["  /msuf reset     - Reset all MSUF frame positions and visibility to defaults."] = "  /msuf reset     - Alle MSUF-Framepositionen und Sichtbarkeit auf Standard zurücksetzen."
L["  /msufdbgpos     - Toggle position drift debugger (overlay + chat log)."] = "  /msufdbgpos     - Positionsdrift-Debugger umschalten (Overlay + Chatlog)."
