L["|cffff0000MSUF WARNING:|r This will delete |cffff0000ALL|r MSUF profiles & settings for this account."] = "|cffff0000MSUF-WARNUNG:|r Dies löscht |cffff0000ALLE|r MSUF-Profile und Einstellungen für diesen Account."
