L["|cffff0000MSUF:|r DB not initialized."] = "|cffff0000MSUF:|r Datenbank nicht initialisiert."
L["|cffff0000MSUF:|r FULL RESET executed - all MSUF profiles & settings deleted for this account."] = "|cffff0000MSUF:|r KOMPLETTRESET ausgeführt - alle MSUF-Profile und Einstellungen für diesen Account gelöscht."
L["|cffff0000MSUF:|r Usage: /msuf gfhoverdebug on|off|status"] = "|cffff0000MSUF:|r Verwendung: /msuf gfhoverdebug on|off|status"
L["|cffff5555MSUF|r: Can't reload UI in combat. Leave combat, then type /reload."] = "|cffff5555MSUF|r: UI kann im Kampf nicht neu geladen werden. Verlasse den Kampf und gib dann /reload ein."
L["|cffff6060CTRL required:|r |cffffffffhold |r|cff55ff55CTRL + Left-Click|r|cffffffff to confirm the anchor target.|r"] = "|cffff6060STRG erforderlich:|r |cffffffffhalte |r|cff55ff55STRG + Linksklick|r|cffffffff, um das Ankerziel zu bestätigen.|r"
L["|cffffcc00MSUF:|r Full reset cancelled. If you still want it, type:"] = "|cffffcc00MSUF:|r Komplettreset abgebrochen. Wenn du ihn weiterhin möchtest, gib ein:"
L["|cffffcc00MSUF:|r Then click: MSUF Menu > Advanced > Factory Reset (or type /reload)."] = "|cffffcc00MSUF:|r Klicke dann: MSUF-Menü > Erweitert > Werkseinstellungen (oder gib /reload ein)."
L["|cffffcc00MSUF:|r Type |cffffff00/msuf fullreset confirm|r to stage the reset."] = "|cffffcc00MSUF:|r Gib |cffffff00/msuf fullreset confirm|r ein, um das Zurücksetzen vorzubereiten."
L["|cffffcc33No named frame found under cursor.|r |cffffffffTry a different spot.|r"] = "|cffffcc33Kein benannter Frame unter dem Cursor gefunden.|r |cffffffffVersuche eine andere Stelle.|r"
L["|cffffd700MSUF:|r Castbar Edit Mode |cff00ff00ON|r drag player/target/focus castbars with the mouse."] = "|cffffd700MSUF:|r Castbar-Bearbeitungsmodus |cff00ff00AN|r: Spieler-/Ziel-/Fokus-Castbars mit der Maus ziehen."
L["|cffffd700MSUF:|r Castbar Edit Mode |cffff0000OFF|r."] = "|cffffd700MSUF:|r Castbar-Bearbeitungsmodus |cffff0000AUS|r."
