L["|cffffff00MSUF:|r Reloading UI to rebuild clean defaults..."] = "|cffffff00MSUF:|r UI wird neu geladen, um saubere Standards neu aufzubauen..."
L["|cffffff00MSUF:|r Reset staged. Please type |cff00ff00/reload|r OR use: MSUF Menu > Advanced > Factory Reset."] = "|cffffff00MSUF:|r Zurücksetzen vorbereitet. Bitte |cff00ff00/reload|r eingeben ODER MSUF-Menü > Erweitert > Werkseinstellungen nutzen."
L["|cffffffffHover a frame, then hold |r|cff55ff55CTRL + Left-Click|r|cffffffff to anchor.  |  Right-Click or Escape cancels.|r"] = "|cffffffffFrame anvisieren, dann |r|cff55ff55STRG + Linksklick|r|cffffffff halten/klicken, um zu ankern.  |  Rechtsklick oder Escape bricht ab.|r"
