L["|cffffffffRight Click:|r Toggle Edit Mode"] = "|cffffffffRechtsklick:|r Bearbeitungsmodus umschalten"
L["|cffffffffShift + Click:|r Open Profiles"] = "|cffffffffUmschalt + Klick:|r Profile öffnen"
L["A %s in your group can provide this."] = "Ein %s in deiner Gruppe kann dies bereitstellen."
L["A calmer setup command center: start with movement, frames, group frames, or a safe profile import."] = "Eine ruhigere Setup-Zentrale: beginne mit Verschieben, Frames, Gruppenframes oder einem sicheren Profilimport."
