L["Add menu scroll edge bounce."] = "Menü-Scroll-Edge-Bounce hinzugefügt."
L["Add Spell..."] = "Zauber hinzufügen..."
L["Added and refined the Menu2 search module."] = "Menu2-Suchmodul hinzugefügt und verfeinert."
L["Added backend compatibility hardening across MSUF modules."] = "Backend-Kompatibilität über MSUF-Module hinweg gehärtet."
L["Added centralized font registry support for the unit frame runtime."] = "Zentrale Schriftregistrierung für die Unitframe-Runtime hinzugefügt."
L["Added class-colored bar background support across unit and group frames."] = "Klassenfarbige Balkenhintergründe für Unit- und Gruppenframes hinzugefügt."
L["Added core swap recolor runtime support."] = "Runtime-Unterstützung für Core-Swap-Recolor hinzugefügt."
L["Added Focus Target frame support across unit settings, edit mode, menu previews, copy targets, text options, icons, and runtime refreshes."] = "Fokusziel-Frame-Unterstützung in Einheiteneinstellungen, Edit Mode, Menüvorschauen, Kopierzielen, Textoptionen, Symbolen und Runtime-Refreshes hinzugefügt."
L["Added improved on/off switch visuals."] = "Verbesserte On/Off-Schalteroptik hinzugefügt."
L["Added more Menu2 cards and refined menu structure."] = "Weitere Menu2-Karten hinzugefügt und Menüstruktur verfeinert."
L["Added more Menu2 cards to group and unit sections."] = "Weitere Menu2-Karten zu Gruppen- und Einheitenbereichen hinzugefügt."
L["Added new Menu2 search module and improved search/guidance text."] = "Neues Menu2-Suchmodul hinzugefügt und Such-/Hinweistexte verbessert."
L["Added new UI/media assets for switches and rounded/superellipse visuals."] = "Neue UI-/Medienassets für Schalter sowie abgerundete und Superellipse-Optik hinzugefügt."
L["Added raid group number display next to unit names."] = "Anzeige der Raidgruppennummer neben Einheitennamen hinzugefügt."
L["Added redesigned Menu2 card layout across unit, group, aura, indicator, bar, and advanced pages."] = "Neu gestaltetes Menu2-Kartenlayout für Einheiten-, Gruppen-, Auren-, Indikator-, Balken- und Erweiterte-Seiten hinzugefügt."
L["Added Rounded Frames with per-surface controls for unit frames, group frames, bars, highlights, overlays, absorbs, and indicators."] = "Abgerundete Frames mit Steuerung pro Oberfläche für Unitframes, Gruppenframes, Balken, Highlights, Overlays, Absorbs und Indikatoren hinzugefügt."
L["Added rounded mask media for the live unit/group frames and Menu2 preview."] = "Abgerundete Maskenmedien für Live-Unit-/Gruppenframes und Menu2-Vorschau hinzugefügt."
L["Added Rounded Texture controls under Global Style > Bars with per-surface toggles, search coverage, localization, preview support, and a reload prompt."] = "Steuerung für Abgerundete Textur unter Globaler Stil > Balken mit Oberflächen-Schaltern, Suchabdeckung, Lokalisierung, Vorschauunterstützung und Reload-Abfrage hinzugefügt."
