L["Blizzard mode lets WoW place the selected aura types. MSUF Custom mode lets MSUF control aura size, growth, position, filters, and styling. Dispel Glow is unavailable only for Group Frame scopes where Blizzard controls the aura layer."] = "Im Blizzard-Modus platziert WoW die ausgewählten Auren-Typen. Im MSUF-Custom-Modus steuert MSUF Größe, Wachstum, Position, Filter und Styling. Dispel Glow ist nur für Gruppenframe-Bereiche nicht verfügbar, in denen Blizzard den Auren-Layer steuert."
L["Blizzard renders cooldown/stack text for native Buffs and Debuffs. These text overlay fields only affect custom icons."] = "Blizzard rendert Abklingzeit- und Stapeltext für native Buffs und Debuffs. Diese Text-Overlay-Felder betreffen nur benutzerdefinierte Symbole."
