L["Defaulted tooltips back to Blizzard-controlled behavior for better compatibility."] = "Tooltips für bessere Kompatibilität wieder standardmäßig Blizzard-gesteuert."
L["Delete profile '%s'?\n\nThis removes the selected profile from MSUF. Other profiles are not affected, but this profile cannot be restored unless you exported or copied it first."] = "Profil '%s' löschen?\n\nDies entfernt das ausgewählte Profil aus MSUF. Andere Profile sind nicht betroffen, aber dieses Profil kann nur wiederhergestellt werden, wenn du es vorher exportiert oder kopiert hast."
