L["Editing %s caps. Use Caps & Icons > Max Buffs = 0 to hide buffs only for this unit; Max Debuffs = 0 hides debuffs."] = "%s-Limits werden bearbeitet. Nutze Limits & Icons > Max. Buffs = 0, um Buffs nur für diese Einheit auszublenden; Max. Debuffs = 0 blendet Debuffs aus."
L["Editing:"] = "Bearbeitet:"
L["EM_HELP_BTN"] = "? Hilfe"
L["EM_HELP_BTN_TIP"] = "Vollständige geführte MSUF-Einrichtung\nbeim Kapitel Bearbeitungsmodus öffnen."
L["EM_HELP_CDM"] = "|cff60a5ffCDM|r schaltet den globalen Essential-Cooldown-Manager-Anker um. |cff60a5ffAnchor|r öffnet die Anker-Auswahl; bewege den Mauszeiger über einen benannten Frame, halte Strg und klicke links, um ihn als globalen Anker zu verwenden. Ein eigener Anker deaktiviert CDM."
L["EM_HELP_COPYTO"] = "In Unit- und Castbar-Popups kopiert |cff60a5ffCopy To|r die Einstellungen des aktuellen Popups zu einem anderen Ziel. Unitframe-Kopien behalten Position und Anker des Ziels; Castbar-Kopien behalten die X/Y-Versätze des Ziels."
L["EM_HELP_DRAG"] = "Halte die linke Maustaste auf einem Mover-Overlay und ziehe es. Der Live-Frame folgt dem Mover, und die X/Y-Anzeige darunter zeigt den aktuellen Bildschirmversatz. Loslassen speichert die Position."
L["EM_HELP_EXIT"] = "|cff60a5ffExit|r verlässt den Bearbeitungsmodus und behält die aktuellen Änderungen. Auch Kampfbeginn verlässt den Bearbeitungsmodus. Escape schließt bzw. bricht ein Popup ab; die HUD-Schaltfläche Exit ist der normale Weg zum Verlassen."
L["EM_HELP_NUDGE"] = "Pfeiltasten bewegen das aktive Ziel. Priorität: ausgewählter Vorschaugriff, offenes Castbar-Popup, offenes Aura-Popup, dann der aktuell ausgewählte Unitframe. Schrittgröße: 1 px, Umschalt = 5 px, Strg = 10 px, Alt = aktueller Rasterabstand."
L["EM_HELP_OPACITY"] = "Scrolle über die Steuerung |cff60a5ffBG ##%|r, um nur die Deckkraft des Bearbeitungsmodus-Hintergrunds zu ändern. Das ändert weder Unitframe-Alpha noch gespeicherte Frame-Sichtbarkeit."
L["EM_HELP_POPUP"] = "Linksklick auf einen Mover ohne Ziehen öffnet dessen Bearbeitungs-Popup. Unit-Popups bearbeiten Framegröße, Position, Textanker, getrennte Ressourcen-Einstellungen und Kopieren-zu-Unit-Optionen. Castbar- und Aura-Mover öffnen eigene fokussierte Popups."
L["EM_HELP_PREVIEW"] = "|cff60a5ffPreview|r schaltet Platzhalterdaten für fehlende Ziele, Fokus, Ziel-des-Ziels, Begleiter, Bosse und Castbar-Vorschauen ein, während der Bearbeitungsmodus aktiv ist. |cff60a5ffAuras|r schaltet Aura-Vorschausymbole und Aura-Mover-Boxen um."
L["EM_HELP_SNAP"] = "Das Raster ist eine visuelle Hilfe. Linksklick auf |cff60a5ffGrid ##px|r schaltet Rasterlinien ein oder aus; Scrollen ändert den Abstand. |cff60a5ffSnap|r ist separat: Wenn aktiv, rasten gezogene Mover an Bildschirmmitte oder Kanten/Mitten anderer sichtbarer Mover ein, mit orangefarbenen Hilfslinien."
L["EM_HELP_TITLE"] = "Bearbeitungsmodus - Kurzübersicht"
L["EM_HELP_UNDO"] = "|cff60a5ffUndo|r und |cff60a5ffRedo|r stellen letzte Bearbeitungsmodus-Änderungen wieder her, die vor Ziehen, Verschieben und Popup-Änderungen erfasst wurden. |cff60a5ffCancel All|r fragt nach Bestätigung, stellt den Snapshot vor Eintritt in den Bearbeitungsmodus wieder her und beendet ihn dann."
