L["Open Group Frames > Health & Text. It controls health colors, bars, power bar, text, dispel overlay, debuff stripe, and range fade. Heal prediction is in Global Style > Bars > Absorb Display."] = "Öffne Gruppenframes > Gesundheit & Text. Dort steuerst du Gesundheitsfarben, Balken, Ressourcenbalken, Text, Dispel-Overlay, Debuff-Streifen und Reichweiten-Fade. Heilungsvorhersage liegt unter Globaler Stil > Balken > Absorb-Anzeige."
L["Open Unit Auras > Global Ignore List. It can hide predefined aura categories for all unit frames, or per unit after enabling Override for this unit. MSUF does not currently have an ElvUI-style freeform spell-ID blacklist for arbitrary debuffs."] = "Öffne Einheiten-Auren > Globale Ignorierliste. Sie kann vordefinierte Aurakategorien für alle Unitframes ausblenden oder pro Einheit, nachdem Überschreiben für diese Einheit aktiviert wurde. MSUF hat derzeit keine ElvUI-ähnliche freie Zauber-ID-Blacklist für beliebige Debuffs."
