L["Skipping this personal step uses neutral guidance and leaves navigation, Search, autosave, Undo/Redo and page reset unexplained."] = "Wähle den Schwerpunkt der Tour und lerne Navigation, Suche, Autosave, Verlauf und Resets kennen."
L["Skipping frame placement leaves whole-frame movement, snapping, nudging and safe exit behavior unexplained."] = "Ganze Frames sicher verschieben, ausrichten und feinjustieren."
L["Skipping the Player frame leaves its layout, text, indicators and aura options unreviewed."] = "Layout, Text, Indikatoren und Auren."
L["Skipping the Target frame leaves its layout, text, indicators and aura options unreviewed."] = "Layout, Text, Indikatoren und Auren."
L["Skipping the Focus frame leaves its layout, text, indicators and aura options unreviewed."] = "Layout, Text, Indikatoren und Auren."
L["Skipping the Pet frame leaves its layout, text, indicators and aura options unreviewed."] = "Layout, Text, Indikatoren und Auren."
L["Skipping Target of target leaves its layout, text and visibility options unreviewed."] = "Layout, Text und Sichtbarkeit."
L["Skipping Focus target leaves its layout, text and visibility options unreviewed."] = "Layout, Text und Sichtbarkeit."
L["Skipping Boss frames leaves their shared layout, text, indicators and aura options unreviewed."] = "Gemeinsames Layout, Text, Indikatoren und Auren."
L["Skipping group layout leaves frame size, growth, sorting, scaling and anchoring unreviewed."] = "Framegröße, Wachstum, Sortierung, Skalierung und Anker."
L["Skipping group bars leaves health, power, text, range and dispel presentation unreviewed."] = "Gesundheit, Ressource, Text, Reichweite und Dispel-Feedback."
L["Skipping group auras leaves group buff, debuff and spell-indicator behavior unreviewed."] = "Gruppen-Buffs, Debuffs und Zauberindikatoren."
L["Skipping Bars leaves global textures, absorbs, outlines, highlights and power behavior unreviewed."] = "Texturen, Absorbs, Konturen, Hervorhebungen und Ressourcenverhalten."
L["Skipping Cast Bars leaves cast appearance, text, empowered casts and interrupt cues unreviewed."] = "Darstellung, Text, ermächtigte Zauber und Unterbrechungshinweise."
L["Skipping Colors leaves frame, power, aura, class, text and castbar colors unreviewed."] = "Frame-, Ressourcen-, Aura-, Klassen-, Text- und Zauberleistenfarben."
L["Skipping Fonts leaves the global font, text styling, colors and name shortening unreviewed."] = "Globale Schrift, Textstil, Farben und Namenskürzung."
L["Skipping Aura styling leaves buff/debuff size, cooldown, stacks, duration bars and ordering unreviewed."] = "Auragröße, Abklingzeiten, Stapel, Dauerleisten und Sortierung."
