L["Preview controls = inspect layouts and states · MSUF Edit Mode = whole-frame placement"] = "Vorschau = Layouts und Zustände prüfen · MSUF-Bearbeitungsmodus = ganzen Frame platzieren"
L["Drag = inner position · gear/double-click = options · right-click = actions · Ctrl-wheel/drag = zoom/pan · Edit Mode = whole frame"] = "Ziehen = innere Position · Zahnrad/Doppelklick = Optionen · Rechtsklick = Aktionen · Strg-Rad/Ziehen = Zoom/Verschieben · Bearbeitungsmodus = ganzer Frame"
L["%s is highlighted. Adjust it live, keep it as is, or continue."] = "%s ist hervorgehoben. Passe es direkt an, lasse es unverändert oder gehe weiter."
