L["Start with Preview, then follow each highlighted frame section."] = "Beginne mit der Vorschau und folge dann jedem hervorgehobenen Frame-Abschnitt."
L["Raid focus: compare Raid and Mythic scopes before reviewing each highlighted section."] = "Raid-Fokus: Vergleiche Raid- und Mythisch-Bereich, bevor du die hervorgehobenen Abschnitte prüfst."
L["Solo focus: keep group defaults or prepare the Party scope for occasional groups."] = "Solo-Fokus: Behalte Gruppenstandards oder bereite den Party-Bereich für gelegentliche Gruppen vor."
