L["Runs a short castbar for the global cooldown whenever an instant spell triggers it.\n\nThe fill and time text are driven natively by the client from the real (haste-scaled) GCD duration - no per-frame addon work while the bar runs. A real cast, channel or empower always takes priority."] = "Zeigt eine kurze Castbar für den Global Cooldown, wenn ein Sofortzauber ihn auslöst.\n\nFüllung und Zeittext werden nativ vom Client aus der echten (Tempo-skalierten) GCD-Dauer gesteuert - keine Addon-Arbeit pro Frame, während die Leiste läuft. Ein echter Zauber, Kanalzauber oder verstärkter Zauber hat immer Vorrang."
L["Shows tick separators on the Player castbar while channeling.\n\nSupported spells use their actual tick count, including supported talent and channel-duration changes. Unsupported channels keep five evenly spaced fallback lines. Custom channel tick settings override the automatic layout.\n\nThe markers are event-driven and add no recurring channel polling."] = "Zeigt Tick-Trennlinien auf der Spieler-Castbar während einer Kanalisierung.\n\nUnterstützte Spells verwenden ihre tatsächliche Tick-Anzahl, einschließlich unterstützter Talent- und Kanalisierungsdauer-Änderungen. Nicht unterstützte Kanalisierungen behalten fünf gleichmäßig verteilte Fallback-Linien. Benutzerdefinierte Channel-Tick-Einstellungen überschreiben das automatische Layout.\n\nDie Marker arbeiten ereignisgesteuert und erzeugen kein wiederkehrendes Channel-Polling."
L["Show spark (leading edge highlight)"] = "Funken an der Vorderkante anzeigen"

L["The Assistant dashboard module is not available. Use the navigation pages and search to configure MSUF."] = "Assistant nicht verfügbar. Nutze Navigation oder Suche, um MSUF einzurichten."
L["Use sliders for exact scale changes. Apply commits the selected value; Revert returns to the active value."] = "Passe einen Regler an und wähle Anwenden. Zurück verwirft den ausstehenden Wert."
L["Changes the global WoW UI scale through MSUF presets."] = "Legt die WoW-UI-Skalierung über eine Vorlage fest."
L["Changes the actual MSUF unit frames in-game."] = "Skaliert alle MSUF-Frames."
L["Changes only this configuration menu window."] = "Skaliert nur dieses Menü."
L["If MSUF helps your UI, support links are one click away."] = "Unterstütze die Entwicklung oder öffne den Quellcode."
L["Continue your MSUF setup"] = "Dein Fortschritt ist gespeichert."
L["Review or run the guided setup again"] = "Du kannst deine Einrichtung jederzeit prüfen."
L["Set up every part of MSUF with guidance"] = "MSUF Schritt für Schritt einrichten."

