L["Priority Frames keep automatic tanks and manually pinned group members in a stable extra strip. In a party they inherit Party Frames; in a raid they inherit the active Raid or Mythic Raid frames. The matching base group frames must be enabled. Open Group Frames > Priority to choose who appears, set a hover hotkey, and place the strip."] = "Prioritätsframes zeigen automatische Tanks und manuell angeheftete Gruppenmitglieder in einer festen Zusatzleiste. In einer Party übernehmen sie die Partyframes, in einem Raid die aktiven Raid- oder Mythic-Raid-Frames. Die passenden Basis-Gruppenframes müssen aktiviert sein. Unter Gruppenframes > Priorität legst du fest, wer angezeigt wird, welches Mouseover-Tastenkürzel gilt und wo die Leiste sitzt."
