L["The same setting as Portrait > More Options. It swaps the portrait for the spell icon while the unit casts, so the portrait has to be enabled."] = "Dieselbe Einstellung wie unter Porträt > More Options. Sie ersetzt das Porträt während des Wirkens durch das Zaubersymbol, das Porträt muss also aktiviert sein."
L["Starts this frame effect when the aura reaches the selected time remaining. Permanent auras never trigger it."] = "Startet diesen Rahmeneffekt, wenn die Aura die ausgewählte verbleibende Zeit erreicht. Permanente Auren lösen es nie aus."
