L["Style stays here under Appearance > Auras. Filters and lists now live directly in each frame's matching Aura menu."] = "Der Stil bleibt hier unter Aussehen > Auren. Filter und Listen sind jetzt direkt im passenden Aura-Menü jedes Frames verfügbar."
L["Switch to Party scope to edit this feature."] = "Wechseln Sie zum Gruppenbereich, um diese Funktion zu bearbeiten."
