L["Text, cooldown, stack and marker styling."] = "Text-, Abklingzeit-, Stapel- und Markierungsstil."
L["Textures, gradients, outlines and highlight borders."] = "Texturen, Farbverläufe, Umrisse und Hervorhebungsränder."
L["The next checkpoint unlocks after a real Party-frame position change."] = "Der nächste Kontrollpunkt wird nach einer echten Positionsänderung des Party-Frames freigeschaltet."
L["The placement step completes after you drag the highlighted frame once."] = "Der Platzierungsschritt ist abgeschlossen, nachdem Sie den hervorgehobenen Rahmen einmal gezogen haben."
