L["Timer and marker colors are shared by unit and group aura previews."] = "Timer- und Markierungsfarben werden in der Einheiten- und Gruppen-Aura-Vorschau gemeinsam genutzt."
L["Timer urgency, ownership, stacks and pandemic state."] = "Timer-Dringlichkeit, Besitz, Stapel und Pandemiezustand."
L["Tune Party range fade"] = "Tune Party-Bereich verblassen"
L["Two arrows point to a movable frame. Drag it once; Next unlocks after a real position change."] = "Zwei Pfeile weisen auf einen beweglichen Rahmen hin. Drag it once; Next wird nach einem echten Positionswechsel freigeschaltet."
L["Type a new value, then press Enter."] = "Geben Sie einen neuen Wert ein und drücken Sie dann die Eingabetaste."
L["UNLOCK, THEN CHANGE IT - Enable Corner Indicators, choose a slot, then select Custom Spell when requested."] = "ENTSPERREN, DANN ÄNDERN – Aktivieren Sie Eckindikatoren, wählen Sie einen Steckplatz und wählen Sie dann bei Aufforderung „Benutzerdefinierter Zauber“ aus."
L["UNLOCK, THEN CHANGE IT - Enable Spell Indicators, choose a spec, then press a tracked spell tile."] = "ENTSPERREN UND DANN ÄNDERN – Aktiviere Zauberindikatoren, wähle eine Spezialisierung und drücke dann auf eine nachverfolgte Zauberkachel."
L["UNLOCK, THEN CHANGE IT - Enable Spell Indicators, choose a spell, then select a Frame Effect."] = "ENTSPERREN UND DANN ÄNDERN – Aktivieren Sie Zauberindikatoren, wählen Sie einen Zauber und dann einen Rahmeneffekt."
L["UNLOCK, THEN CHANGE IT - Enable Spell Indicators, choose a spell, then set Indicator Type."] = "ENTSPERREN, DANN ÄNDERN – Zauberindikatoren aktivieren, einen Zauber auswählen und dann den Indikatortyp festlegen."
L["UNLOCK, THEN CHANGE IT - Enable the parent feature in this section first."] = "ENTSPERREN, DANN ÄNDERN – Aktivieren Sie zuerst die übergeordnete Funktion in diesem Abschnitt."
L["UNLOCK, THEN CHANGE IT - Turn on Spell Indicators in the earlier checkpoint; use Back if you skipped it."] = "ENTSPERREN, DANN ÄNDERN – Aktivieren Sie die Zauberanzeigen im früheren Kontrollpunkt; Verwenden Sie Zurück, wenn Sie es übersprungen haben."
L["Unit frame status icons are on each unit page. Group Spell Indicators are in Group Frames > Auras; group status and corner indicators are in Group Frames > Status & Indicators."] = "Die Statussymbole des Unitframes liegen auf jeder Einheitenseite. Gruppenzauber-Indikatoren findest du unter Gruppenframes > Auren; Gruppenstatus- und Eckindikatoren unter Gruppenframes > Status & Indikatoren."
L["Unitframe Cooldown Manager anchoring"] = "Verankerung des Unitframe Cooldown Managers"
L["Unitframe auras"] = "Unitframe-Auren"
L["Unitframe castbar"] = "Unitframe-Zauberleiste"
L["Use Global"] = "Verwenden Sie Global"
