L["Use Global Style > Bars for highlight borders and Group Frames > Status & Indicators for role, threat, dispel, corner, and raid-marker indicators. Spell Indicators are in Group Frames > Auras."] = "Verwenden Sie „Globaler Stil“ > „Balken“ zum Hervorheben von Rändern und „Gruppenrahmen“ > „Status & Indikatoren“ für Rollen-, Bedrohungs-, Bannungs-, Ecken- und Überfallmarkierungsindikatoren. Zauberindikatoren finden Sie unter Gruppenrahmen > Auren."
L["Use Global follows the Unitframe Global Coloring mode from Colors. Other choices override only this frame."] = "Use Global folgt dem Unitframe Global Coloring-Modus von Colors. Andere Auswahlmöglichkeiten überschreiben nur diesen Rahmen."
