L["YOUR MOVE - Open Edit Mode, drag Party Frames once, then click the mover to see its Width, Height, and Spacing popup."] = "IHRE BEWEGUNG – Öffnen Sie den Bearbeitungsmodus, ziehen Sie die Gruppenrahmen einmal und klicken Sie dann auf den Beweger, um das Popup-Fenster für Breite, Höhe und Abstand anzuzeigen."
