-- MSUF FULL CORE MENU SOURCE INVENTORY 2
-- Generated missing non-Assistant core keys for deDE.
L["+"] = "+"
L["Can Priority Frames automatically select healers, DPS, classes, or specs?"] = "Können Priority Frames automatisch Heiler, DPS, Klassen oder Spezifikationen auswählen?"
L["Can Priority Frames automatically show Augmentation Evokers?"] = "Können Priority Frames Augmentation Evokers automatisch anzeigen?"
L["Can Priority Frames show my co-tank?"] = "Können Priority Frames meinen Co-Tank anzeigen?"
L["Can Priority Frames update during combat?"] = "Können Prioritätsrahmen während des Kampfes aktualisiert werden?"
L["Check that Priority Frames are enabled, you are grouped, and the matching base Party or Raid frames are enabled. Confirm that an assigned tank or manually pinned player is currently in the group and Visible slots is not full. Saved absent players create no empty placeholders, and protected roster changes made in combat finish after combat ends."] = "Überprüfen Sie, ob Prioritätsrahmen aktiviert sind, Sie gruppiert sind und die entsprechenden Basis-Party- oder Raid-Rahmen aktiviert sind. Bestätigen Sie, dass sich derzeit ein zugewiesener Panzer oder ein manuell angehefteter Spieler in der Gruppe befindet und die sichtbaren Plätze nicht voll sind. Gespeicherte abwesende Spieler erstellen keine leeren Platzhalter und geschützte Kaderänderungen, die im Kampf vorgenommen werden, enden nach Kampfende."
L["Class Color and Health Gradient are runtime colors, not a single editable swatch."] = "Klassenfarbe und Gesundheitsverlauf sind Laufzeitfarben und kein einzelnes bearbeitbares Farbfeld."
L["Cleave Training Dummy"] = "Cleave-Trainingspuppe"
L["Custom 1-3 are always stored per frame. Icon styling and Full-Frame effects here only change "] = "Benutzerdefiniert 1–3 werden immer pro Frame gespeichert. Hier ändern sich lediglich der Symbolstil und die Vollbildeffekte"
L["Disabled or whitelist empty"] = "Deaktiviert oder Whitelist leer"
L["Do Priority Frame pins persist, and what order do they use?"] = "Bleiben Priority Frame-Pins bestehen und welche Reihenfolge haben sie?"
L["Do Priority Frames inherit click casting and appearance?"] = "Erben Priority Frames Klick-Casting und Aussehen?"
L["Do Priority Frames use polling?"] = "Nutzen Priority Frames Polling?"
L["Do Priority Frames work in parties and dungeons?"] = "Funktionieren Priority Frames in Gruppen und Dungeons?"
L["Enter text"] = "Geben Sie Text ein"
L["Existing Priority frames remain usable in combat, but WoW protects secure group-frame membership and layout changes. Any pin, roster, slot, or placement change that needs a secure refresh is applied after combat ends. Change the Priority Frames keybinding out of combat."] = "Bestehende Prioritätsrahmen bleiben im Kampf verwendbar, WoW schützt jedoch die sichere Gruppenrahmenmitgliedschaft und Layoutänderungen. Jede Pin-, Dienstplan-, Slot- oder Platzierungsänderung, die eine sichere Aktualisierung erfordert, wird nach Ende des Kampfes übernommen. Ändern Sie die Tastenbelegung für Prioritätsrahmen außerhalb des Kampfes."
L["Follows Unitframe Global Coloring. The swatch previews the current global bar color."] = "Folgt der globalen Farbgebung von Unitframe. Das Farbfeld zeigt eine Vorschau der aktuellen globalen Balkenfarbe an."
L["For Priority Frames, layout is profile-wide, while pins are character-specific. Visible slots can be set from one to five. Automatic tanks fill first, followed by manual pins in saved order; duplicate selections appear once. A saved player who is absent waits until that player rejoins the current group."] = "Bei Priority Frames gilt das Layout für das gesamte Profil, während die Pins zeichenspezifisch sind. Sichtbare Slots können von eins bis fünf eingestellt werden. Automatische Tanks füllen sich zuerst, gefolgt von manuellen Stiften in gespeicherter Reihenfolge; Doppelte Auswahlen werden einmal angezeigt. Ein gespeicherter Spieler, der abwesend ist, wartet, bis dieser Spieler wieder der aktuellen Gruppe beitritt."
L["Frames"] = "Rahmen"
L["How do I pin or unpin a player in Priority Frames?"] = "Wie kann ich einen Spieler in Priority Frames anheften oder loslösen?"
L["How do I position Priority Frames?"] = "Wie positioniere ich Priority Frames?"
L["How should an Augmentation Evoker use Priority Frames?"] = "Wie sollte ein Augmentation Evoker Priority Frames verwenden?"
L["Inherited: this scope follows Shared aura style. Enable custom aura style only when this scope needs different text, swipe, border, or timer settings."] = "Vererbt: Dieser Bereich folgt dem Shared-Aura-Stil. Aktivieren Sie den benutzerdefinierten Aura-Stil nur, wenn dieser Bereich andere Text-, Wisch-, Rahmen- oder Timereinstellungen benötigt."
L["Leave text"] = "Text hinterlassen"
L["Live "] = "Lebe"
L["Live preview is unavailable for this container. Sample mode remains available."] = "Für diesen Container ist keine Live-Vorschau verfügbar. Der Sample-Modus bleibt verfügbar."
L["Live preview updates after combat. Sample mode remains available."] = "Live-Vorschau-Updates nach dem Kampf. Der Sample-Modus bleibt verfügbar."
L["Manually pin the teammates you want to keep visible for monitoring or click-casting. Priority Frames does not decide who should receive Prescience or Ebon Might. Configure Group Frames > Auras > Spell Indicators if you want inherited Priority frames to show Prescience, Ebon Might, Shifting Sands, Blistering Scales, or other configured effects."] = "Pinnen Sie manuell die Teamkollegen an, die Sie zur Überwachung oder zum Click-Casting sichtbar halten möchten. Priority Frames entscheiden nicht darüber, wer Prescience oder Ebon Might erhalten soll. Konfigurieren Sie Gruppenrahmen > Auren > Zauberindikatoren, wenn Sie möchten, dass geerbte Prioritätsrahmen Vorahnung, Ebenholzmacht, Wandersand, Blasenschuppen oder andere konfigurierte Effekte anzeigen."
L["Mouseover highlight"] = "Mouseover-Highlight"
L["Native · "] = "Einheimisch ·"
L["No continuous polling ticker or OnUpdate loop is used for Priority selection. It resolves the roster when configuration, pins, group state, or relevant unit identity changes require a refresh. Automatic selection reads WoW's assigned TANK role and does not inspect every group member's specialization in the background."] = "Für die Prioritätsauswahl wird kein kontinuierlicher Polling-Ticker oder eine OnUpdate-Schleife verwendet. Es löst den Dienstplan auf, wenn Konfiguration, Pins, Gruppenstatus oder relevante Einheitenidentitätsänderungen eine Aktualisierung erfordern. Die automatische Auswahl liest die von WoW zugewiesene TANK-Rolle und überprüft nicht die Spezialisierung jedes Gruppenmitglieds im Hintergrund."
L["No live "] = "Kein Leben"
L["No live member"] = "Kein Live-Mitglied"
L["No matching aura active"] = "Keine passende Aura aktiv"
L["No. Automatic selection currently uses only WoW's assigned TANK role. Healers, DPS, classes, specializations, and support targets must be pinned manually with the hover hotkey. This avoids background inspection or polling and keeps the selection deterministic."] = "Nein. Die automatische Auswahl verwendet derzeit nur die von WoW zugewiesene TANK-Rolle. Heiler, DPS, Klassen, Spezialisierungen und Unterstützungsziele müssen manuell mit dem Hover-Hotkey angeheftet werden. Dadurch werden Hintergrundprüfungen oder Abfragen vermieden und die Auswahl bleibt deterministisch."
L["OFF"] = "AUS"
L["ON"] = "EIN"
L["Open Group Frames > Priority > Placement. Attach the strip to the right, left, top, or bottom of the active Party/Raid container, or choose Free position and use the dedicated Priority Frames mover in Edit Mode. The same page controls growth, spacing, attachment gap, and alignment offset."] = "Öffnen Sie Gruppenrahmen > Priorität > Platzierung. Befestigen Sie den Streifen rechts, links, oben oder unten am aktiven Party-/Raid-Container oder wählen Sie die freie Position und verwenden Sie den speziellen Priority Frames Mover im Bearbeitungsmodus. Die gleiche Seite steuert Wachstum, Abstand, Anhangslücke und Ausrichtungsversatz."
L["Options"] = "Optionen"
L["Override active: this scope keeps its own aura style. Shared style changes will not replace it until the override is reset."] = "Override aktiv: Dieses Zielfernrohr behält seinen eigenen Aura-Stil. Gemeinsame Stiländerungen ersetzen ihn erst, wenn die Überschreibung zurückgesetzt wird."
L["Priority Frames does not automatically detect other players' specializations. Automatic selection currently supports WoW-assigned tanks only. Pin an Augmentation Evoker manually with the hover hotkey; Priority Frames does not choose ideal Prescience or Ebon Might targets."] = "Priority Frames erkennt die Spezialisierungen anderer Spieler nicht automatisch. Die automatische Auswahl unterstützt derzeit nur WoW-zugewiesene Panzer. Hängen Sie einen Augmentation Evoker manuell mit dem Hover-Hotkey an; Priority Frames wählt keine idealen Prescience- oder Ebon Might-Ziele aus."
L["Priority Frames duplicate automatic tanks and manually pinned current group members into a stable extra strip without removing them from the normal Party or Raid frames. In a party they inherit Party Frames; in a raid they inherit the active Raid or Mythic Raid frames. They work in parties, raids, and Mythic raids, inherit the active group-frame click-cast behavior, and require the matching base group frames to be enabled."] = "Prioritätsrahmen duplizieren automatische Panzer und manuell fixierte aktuelle Gruppenmitglieder in einem stabilen Extrastreifen, ohne sie aus den normalen Gruppen- oder Raidrahmen zu entfernen. In einer Gruppe erben sie Parteirahmen; In einem Raid erben sie die aktiven Raid- oder Mythic Raid-Frames. Sie funktionieren in Gruppen, Raids und mythischen Raids, erben das Click-Cast-Verhalten des aktiven Gruppenrahmens und erfordern die Aktivierung der entsprechenden Basisgruppenrahmen."
L["Rested"] = "Ausgeruht"
L["Shared aura style is the baseline for unit-frame aura text, swipe, border, and timer settings. Party and Raid are group-frame style scopes with their own settings."] = "Der gemeinsame Aura-Stil ist die Basis für die Aura-Text-, Wisch-, Rahmen- und Timer-Einstellungen für Einheitsrahmen. Party und Raid sind Gruppenrahmen-Zielfernrohre mit eigenen Einstellungen."
L["Textures are shared except Party/Raid group-frame overrides. Gradients can be customized per unit or group scope."] = "Texturen werden gemeinsam genutzt, mit Ausnahme von Gruppen-/Raid-Gruppenrahmen-Überschreibungen. Farbverläufe können pro Einheit oder Gruppenbereich angepasst werden."
L["This group scope can use custom textures and gradients. Raid also applies to Mythic Raid."] = "Dieser Gruppenbereich kann benutzerdefinierte Texturen und Farbverläufe verwenden. Raid gilt auch für Mythic Raid."
L["This scope can use custom gradients and bar settings. Textures still follow Shared."] = "Dieser Bereich kann benutzerdefinierte Farbverläufe und Balkeneinstellungen verwenden. Texturen folgen weiterhin Shared."
L["This scope follows Shared bar settings. Turn on custom settings here when this scope needs different gradients or bar settings."] = "Dieser Bereich folgt den Einstellungen der geteilten Leiste. Aktivieren Sie hier benutzerdefinierte Einstellungen, wenn dieses Zielfernrohr andere Farbverläufe oder Balkeneinstellungen benötigt."
L["Updates after combat"] = "Updates nach dem Kampf"
L["Where can I request a Priority Frames feature?"] = "Wo kann ich eine Priority Frames-Funktion anfordern?"
L["While grouped, set the hover hotkey on Group Frames > Priority. Hover an MSUF Party, Raid, or Priority frame and press the Priority Frames hotkey to pin or unpin that player. Players cannot be added by typing a name or while outside the current group; a saved absent pin waits and reappears when that player rejoins."] = "Legen Sie beim Gruppieren den Hover-Hotkey auf Gruppenrahmen > Priorität fest. Bewegen Sie den Mauszeiger über einen MSUF-Party-, Raid- oder Prioritätsrahmen und drücken Sie den Hotkey „Prioritätsrahmen“, um diesen Spieler anzuheften oder zu lösen. Spieler können nicht durch Eingabe eines Namens oder außerhalb der aktuellen Gruppe hinzugefügt werden; Ein gespeicherter Abwesenheits-Pin wartet und erscheint wieder, wenn dieser Spieler wieder beitritt."
L["Why are my Priority Frames empty or missing?"] = "Warum sind meine Prioritätsrahmen leer oder fehlen?"
L["Yes. Include tanks automatically selects current group members whose WoW-assigned role is TANK, normally including both you and your co-tank. To show only your co-tank, disable automatic tanks and manually pin the other tank. If WoW has not assigned that player the TANK role, manual pinning is the fallback."] = "Ja. „Tanks einbeziehen“ wählt automatisch aktuelle Gruppenmitglieder aus, deren WoW-zugeordnete Rolle TANK ist, zu denen normalerweise sowohl Sie als auch Ihr Co-Tank gehören. Um nur Ihren Co-Tank anzuzeigen, deaktivieren Sie die automatischen Tanks und pinnen Sie den anderen Tank manuell an. Wenn WoW diesem Spieler nicht die TANK-Rolle zugewiesen hat, ist manuelles Anheften die Alternative."
L["Yes. Priority Frames inherit the active Party, Raid, or Mythic Raid frame appearance, including configured bars, text, auras, status indicators, and spell indicators. They use the same MSUF click-casting registration and unit behavior, so existing click-cast bindings also work on the duplicated frames."] = "Ja. Prioritätsrahmen übernehmen das Erscheinungsbild des aktiven Party-, Raid- oder Mythic Raid-Rahmens, einschließlich konfigurierter Balken, Texte, Auren, Statusanzeigen und Zauberanzeigen. Sie verwenden die gleiche MSUF-Click-Cast-Registrierung und das gleiche Einheitenverhalten, sodass vorhandene Click-Cast-Bindungen auch auf die duplizierten Frames funktionieren."
L["Yes. Priority Frames work in parties, raids, and Mythic raids. In a party or dungeon they inherit Party Frames; in a raid they inherit the active Raid or Mythic Raid setup. They do not create a solo strip, and the matching base Party or Raid frames must be enabled."] = "Ja. Prioritätsrahmen funktionieren in Gruppen, Raids und mythischen Raids. In einer Gruppe oder einem Dungeon erben sie Gruppenrahmen; In einem Raid erben sie das aktive Raid- oder Mythic Raid-Setup. Sie erstellen keinen Solo-Strip und die passenden Basis-Party- oder Raid-Frames müssen aktiviert sein."
