L["Solid draws a crisp pixel ring around the icon. Soft Glow adds a halo, and Shadow shades the icon's own edges. The Blizzard entries and any LibSharedMedia border are drawn as edge art. Thickness scales the edge."] = "Einfarbig zeichnet einen scharfen Pixelrand um das Symbol. Weiches Leuchten ergänzt einen Schein, und Schatten schattiert die Kanten des Symbols selbst. Die Blizzard-Einträge und jeder LibSharedMedia-Rand werden als Kantengrafik gezeichnet. Die Dicke skaliert die Kante."
--- Slash command registry (6.0 Beta 29)
L["Frames and Edit Mode"] = "Frames und Bearbeitungsmodus"
L["Profiles and resets"] = "Profile und Zurücksetzen"
L["Other commands"] = "Weitere Befehle"
L["Type /msuf help all to also list the diagnostic commands."] = "Gib /msuf help all ein, um auch die Diagnosebefehle aufzulisten."
L["List every MSUF command that is currently loaded."] = "Listet alle aktuell geladenen MSUF-Befehle auf."
L["Print the addon version, the active profile and the Edit Mode state."] = "Gibt die Addon-Version, das aktive Profil und den Bearbeitungsmodus aus."
L["Reload the interface, same as /rl."] = "Lädt die Benutzeroberfläche neu, wie /rl."
L["Reload the interface."] = "Lädt die Benutzeroberfläche neu."
L["Toggle the absorb bars on and off."] = "Schaltet die Absorptionsleisten ein und aus."
L["List your profiles, or save the current settings as a new profile."] = "Listet deine Profile auf oder speichert die aktuellen Einstellungen als neues Profil."
L["Load one of your saved profiles."] = "Lädt eines deiner gespeicherten Profile."
L["Delete one of your saved profiles. Repeat the command to confirm."] = "Löscht eines deiner gespeicherten Profile. Wiederhole den Befehl zur Bestätigung."
L["Reset all frame positions and visibility to the defaults."] = "Setzt alle Frame-Positionen und die Sichtbarkeit auf die Standardwerte zurück."
L["Reset every setting in the active profile back to the defaults."] = "Setzt jede Einstellung im aktiven Profil auf die Standardwerte zurück."
L["Delete every MSUF profile and setting on this account."] = "Löscht alle MSUF-Profile und Einstellungen dieses Accounts."
L["Turn the Wago Analytics beta telemetry on or off."] = "Schaltet die Wago-Analytics-Beta-Telemetrie ein oder aus."
L["Debug the group-frame hover and tooltip paths."] = "Debuggt die Hover- und Tooltip-Pfade der Gruppenframes."
L["Print the keyboard-capture frames for movement-lock diagnosis."] = "Gibt die Tastatur-abfangenden Frames zur Diagnose blockierter Bewegung aus."
L["Toggle MSUF Edit Mode. Add a unit such as player or target to open it there."] = "Schaltet den MSUF-Bearbeitungsmodus um. Gib eine Einheit wie player oder target an, um dort zu starten."
L["Leave MSUF Edit Mode."] = "Beendet den MSUF-Bearbeitungsmodus."
L["Search the options menu and open the matching settings."] = "Durchsucht das Optionsmenü und öffnet die passenden Einstellungen."
L["Start or resume the guided setup."] = "Startet die geführte Einrichtung oder setzt sie fort."
L["Report how much of the current language is translated."] = "Meldet, wie viel der aktuellen Sprache übersetzt ist."
L["Fake an available update to test the version-check popup."] = "Simuliert ein verfügbares Update, um das Versions-Popup zu testen."
L["Replay the first-start flow or the upgrade highlights."] = "Spielt den Erststart-Ablauf oder die Upgrade-Highlights erneut ab."
L["Profile which events drive the group frames in combat."] = "Misst, welche Ereignisse die Gruppenframes im Kampf antreiben."
L["Dump the aura frame levels for a layering bug report."] = "Gibt die Frame-Ebenen der Auren für einen Layering-Fehlerbericht aus."
L["Check the options menu for structural problems."] = "Prüft das Optionsmenü auf strukturelle Probleme."
L["Toggle the position drift debugger."] = "Schaltet den Positionsdrift-Debugger um."
L["  Profile: %s (%d saved)"] = "  Profil: %s (%d gespeichert)"
L["  Edit Mode: %s - In combat: %s"] = "  Bearbeitungsmodus: %s - Im Kampf: %s"
L["|cffff0000MSUF:|r The profile module is not loaded."] = "|cffff0000MSUF:|r Das Profilmodul ist nicht geladen."
L["|cff00b7ebMSUF|r profiles:"] = "|cff00b7ebMSUF|r Profile:"
L["  /msuf load <name> switches profile, /msuf profile <name> saves a new one."] = "  /msuf load <name> wechselt das Profil, /msuf profile <name> speichert ein neues."
L["|cffff0000MSUF:|r Cannot change profiles while in combat."] = "|cffff0000MSUF:|r Im Kampf kann das Profil nicht gewechselt werden."
L["|cffffcc00MSUF:|r Usage: /msuf load <name>. Type /msuf profile to list them."] = "|cffffcc00MSUF:|r Verwendung: /msuf load <name>. Gib /msuf profile ein, um sie aufzulisten."
L["|cffff0000MSUF:|r '%s' matches more than one profile. Type the full name."] = "|cffff0000MSUF:|r '%s' passt auf mehrere Profile. Gib den vollen Namen ein."
L["|cffff0000MSUF:|r Unknown profile '%s'. Type /msuf profile to list them."] = "|cffff0000MSUF:|r Unbekanntes Profil '%s'. Gib /msuf profile ein, um sie aufzulisten."
L["|cffffd700MSUF:|r Profile '%s' is already active."] = "|cffffd700MSUF:|r Profil '%s' ist bereits aktiv."
L["|cffffcc00MSUF:|r Usage: /msuf delete <name>. Type /msuf profile to list them."] = "|cffffcc00MSUF:|r Verwendung: /msuf delete <name>. Gib /msuf profile ein, um sie aufzulisten."
L["|cffffcc00MSUF:|r Repeat |cffffff00/msuf delete %s|r to delete that profile for good."] = "|cffffcc00MSUF:|r Wiederhole |cffffff00/msuf delete %s|r, um dieses Profil endgültig zu löschen."
L["|cffff0000MSUF:|r Cannot reset a profile while in combat."] = "|cffff0000MSUF:|r Im Kampf kann kein Profil zurückgesetzt werden."
L["|cffffcc00MSUF:|r This resets every setting in profile '%s', not just positions."] = "|cffffcc00MSUF:|r Das setzt jede Einstellung im Profil '%s' zurück, nicht nur die Positionen."
L["|cffffcc00MSUF:|r Type |cffffff00/msuf default confirm|r to go ahead."] = "|cffffcc00MSUF:|r Gib |cffffff00/msuf default confirm|r ein, um fortzufahren."
L["|cffffcc00MSUF:|r Type |cffffff00/msuf default|r first, then confirm it."] = "|cffffcc00MSUF:|r Gib zuerst |cffffff00/msuf default|r ein und bestätige dann."
L["|cffff0000MSUF:|r Unknown frame '%s'. Try player, target, focus, pet, boss or priority."] = "|cffff0000MSUF:|r Unbekannter Frame '%s'. Versuche player, target, focus, pet, boss oder priority."
