L["The resource color follows Player power. A matched background is derived from Health instead."] = "Die Ressourcenfarbe folgt der Spielerressource. Ein passender Hintergrund wird stattdessen aus den Lebenspunkten abgeleitet."
L["The foreground follows the selected HP color mode. Dark Mode uses the shared dark-tone control."] = "Der Vordergrund folgt dem gewählten LP-Farbmodus. Der Dunkelmodus nutzt die gemeinsame Dunkelton-Einstellung."
L["Foreground follows the selected group color mode; editable group colors are shared by Party, Raid and Mythic Raid."] = "Der Vordergrund folgt dem gewählten Gruppenfarbmodus; die bearbeitbaren Gruppenfarben teilen sich Gruppe, Schlachtzug und Mythic-Schlachtzug."
L["Health and Power gradient colors for the selected Bars scope."] = "Verlaufsfarben für Lebens- und Ressourcenleiste im gewählten Balkenbereich."
L["Colors available to the border modes in this card."] = "Farben, die den Randmodi in dieser Karte zur Verfügung stehen."
L["Shared castbar background and outline colors."] = "Gemeinsame Hintergrund- und Umrissfarben der Zauberleiste."
L["Player colors follow the active override mode."] = "Die Spielerfarben folgen dem aktiven Überschreibungsmodus."
L["The shown colors follow the selected indicator style."] = "Die angezeigten Farben folgen dem gewählten Indikatorstil."
L["These colors are shared from the Colors page."] = "Diese Farben stammen aus der Farbenseite."
L["Used when melee-range coloring is enabled."] = "Wird verwendet, wenn die Nahkampfreichweiten-Einfärbung aktiv ist."
L["Used by the Castbar icon-border style."] = "Wird vom Symbolrand-Stil der Zauberleiste verwendet."
L["Used only when the power bar is detached from the frame."] = "Wird nur verwendet, wenn die Ressourcenleiste vom Frame abgetrennt ist."
L["Outline and fill behavior."] = "Verhalten von Umriss und Füllung."
L["Opacity values used by range and offline states."] = "Deckkraftwerte für Reichweiten- und Offline-Zustände."
L["Width can use manual bounds or follow another frame."] = "Die Breite kann manuelle Grenzen nutzen oder einem anderen Frame folgen."
L["Power textures live on the Bars page."] = "Ressourcentexturen findest du auf der Balkenseite."
L["When anchored here, Player power settings are managed by Class Resources."] = "Wenn hier verankert, werden die Spielerressourcen-Einstellungen von den Klassenressourcen verwaltet."
L["Font face follows Shared; text and color mode mirror Player HP."] = "Die Schriftart folgt „Gemeinsam“; Text und Farbmodus spiegeln die Spieler-LP."
L["Local HP text uses shared face settings and a fixed white color."] = "Der lokale LP-Text nutzt die gemeinsamen Schriftarteinstellungen und ein festes Weiß."
L["Synchronized with Text Colors in the Fonts menu for this scope."] = "Synchronisiert mit „Textfarben“ im Schriftenmenü für diesen Bereich."
L["Open the shared font and colors used by every Aura scope."] = "Öffnet die gemeinsame Schrift und die Farben, die alle Aura-Bereiche verwenden."
L["Tints unit-frame health bars when a configured debuff condition is active."] = "Färbt die Lebensleisten der Unitframes, wenn eine eingestellte Debuff-Bedingung zutrifft."
L["Shows a symbol naming the dispel type of an active debuff."] = "Zeigt ein Symbol, das den Entzauberungstyp eines aktiven Debuffs benennt."
L["Shows the raid subgroup number from the raid roster."] = "Zeigt die Untergruppennummer aus der Schlachtzugsliste."
L["Shows the raid subgroup number. Party frames only display it while you are in an actual raid group."] = "Zeigt die Untergruppennummer. Gruppenframes zeigen sie nur, solange du in einem echten Schlachtzug bist."
L["Independent of mouseover. Marks your current target in the selected group-frame types."] = "Unabhängig vom Mouseover. Markiert dein aktuelles Ziel in den gewählten Gruppenframe-Arten."
L["Configure target highlighting in Appearance > Miscellaneous > Frame Highlights."] = "Die Zielhervorhebung stellst du unter Darstellung > Sonstiges > Frame-Hervorhebungen ein."
