L["Changing this value selects Manual width. For Player, it also turns off Sync width to Class Resource so the new width takes effect immediately."] = "Durch Ändern dieses Werts wird Manuelle Breite ausgewählt. Beim Spieler wird außerdem Breite mit Klassenressource synchronisieren deaktiviert, damit die neue Breite sofort wirksam wird."
L["Edits the selected child element's local X offset. Positive values move right. Arrow keys and dragging update the same offset."] = "Bearbeitet den lokalen X-Versatz des ausgewählten untergeordneten Elements. Positive Werte verschieben es nach rechts. Pfeiltasten und Ziehen aktualisieren denselben Versatz."
L["Edits the selected child element's local Y offset. Positive values move up. Arrow keys and dragging update the same offset."] = "Bearbeitet den lokalen Y-Versatz des ausgewählten untergeordneten Elements. Positive Werte verschieben es nach oben. Pfeiltasten und Ziehen aktualisieren denselben Versatz."
